  "error": {
    "code": "CLI_AUTH_REQUIRED",
    "message": "No Outrank API key is configured."
  },
  "agent_guidance": "Run `outrank-cli auth login <api-key>` to store a key locally, or set OUTRANK_API_KEY in the environment before retrying."
}

